import pytest
import cart


# ---------- apply_discount ----------
@pytest.mark.parametrize(
    "price, percent, expected",
    [
        (200, 15, 170.0),
        (100, 0, 100.0),
        (150, 50, 75.0),
    ],
)
def test_apply_discount_valid(price, percent, expected):
    assert cart.apply_discount(price, percent) == expected


@pytest.mark.parametrize(
    "price, percent",
    [
        (-10, 20),   # negative price
        (100, -5),   # percent < 0
        (100, 105),  # percent > 100
    ],
)
def test_apply_discount_invalid(price, percent):
    with pytest.raises(ValueError):
        cart.apply_discount(price, percent)


# ---------- bulk_discount_percent ----------
@pytest.mark.parametrize(
    "quantity, expected",
    [
        (5, 0),
        (10, 5),
        (50, 10),
        (100, 15),
        (150, 15),
    ],
)
def test_bulk_discount_percent(quantity, expected):
    assert cart.bulk_discount_percent(quantity) == expected


@pytest.mark.parametrize(
    "quantity",
    [
        0,
        -1,
        3.5,
    ],
)
def test_bulk_discount_percent_invalid(quantity):
    with pytest.raises(ValueError):
        cart.bulk_discount_percent(quantity)


# ---------- parse_coupon ----------
@pytest.mark.parametrize(
    "code, expected",
    [
        ("SAVE10", 10),
        ("save20", 20),
        (" SAVE30 ", 30),
    ],
)
def test_parse_coupon_valid(code, expected):
    assert cart.parse_coupon(code) == expected


@pytest.mark.parametrize(
    "code",
    [
        "SAVEBAD",     # missing number
        "SAVE0",       # N < 1
        "SAVE51",      # N > 50
        "INVALID",     # wrong prefix
        "save",        # no number
        "   ",         # only whitespace
    ],
)
def test_parse_coupon_invalid(code):
    with pytest.raises(ValueError):
        cart.parse_coupon(code)


# ---------- shipping_fee ----------
@pytest.mark.parametrize(
    "subtotal, member, expected",
    [
        (500, False, 60),
        (1500, True, 0),
        (1200, False, 0),
        (300, True, 30),
    ],
)
def test_shipping_fee(subtotal, member, expected):
    assert cart.shipping_fee(subtotal, member) == expected


@pytest.mark.parametrize(
    "subtotal",
    [
        -10,
        -1.5,
    ],
)
def test_shipping_fee_invalid(subtotal):
    with pytest.raises(ValueError):
        cart.shipping_fee(subtotal)


# ---------- Cart ----------
class TestCart:
    def setup_method(self):
        self.cart = cart.Cart()

    # add_item
    @pytest.mark.parametrize(
        "name, unit_price, quantity",
        [
            ("apple", 1.0, 3),
            ("banana", 0.5, 2),
        ],
    )
    def test_add_item_new(self, name, unit_price, quantity):
        self.cart.add_item(name, unit_price, quantity)
        assert self.cart.items() == {name: (unit_price, quantity)}

    @pytest.mark.parametrize(
        "name, unit_price, quantity",
        [
            ("apple", 1.0, 2),
        ],
    )
    def test_add_item_increment(self, name, unit_price, quantity):
        self.cart.add_item(name, unit_price, 3)
        self.cart.add_item(name, unit_price, quantity)
        assert self.cart.items()[name] == (unit_price, 5)

    @pytest.mark.parametrize(
        "name, unit_price, new_unit_price",
        [
            ("apple", 1.0, 2.0),
        ],
    )
    def test_add_item_mismatched_price(self, name, unit_price, new_unit_price):
        self.cart.add_item(name, unit_price, 1)
        with pytest.raises(ValueError):
            self.cart.add_item(name, new_unit_price, 1)

    @pytest.mark.parametrize(
        "unit_price, quantity",
        [
            (-5, 3),
            (10, -2),
            (3.5, 0),  # zero quantity
            ("abc", 2),
        ],
    )
    def test_add_item_invalid(self, unit_price, quantity):
        with pytest.raises(ValueError):
            self.cart.add_item("item", unit_price, quantity)

    # remove_item
    def test_remove_item_partial(self):
        self.cart.add_item("apple", 1.0, 5)
        self.cart.remove_item("apple", 2)
        assert self.cart.items()["apple"] == (1.0, 3)

    def test_remove_item_to_zero(self):
        self.cart.add_item("banana", 0.5, 4)
        self.cart.remove_item("banana", 4)
        assert "banana" not in self.cart.items()

    def test_remove_nonexistent(self):
        with pytest.raises(KeyError):
            self.cart.remove_item("orange", 1)

    # subtotal
    def test_subtotal_empty(self):
        assert self.cart.subtotal() == 0

    def test_subtotal_multiple_items(self):
        self.cart.add_item("apple", 2.0, 3)   # 6.0
        self.cart.add_item("banana", 1.5, 4) # 6.0
        assert self.cart.subtotal() == 12.0

    # total with discounts and coupons
    def test_total_no_discount(self):
        self.cart.add_item("apple", 10.0, 2)
        assert self.cart.total(member=False, coupon=None) == 20.0

    def test_total_member_shipping_free(self):
        self.cart.add_item("item", 2000.0, 1)
        assert self.cart.total(member=True, coupon=None) == 2000.0

    @pytest.mark.parametrize(
        "quantity, expected_percent",
        [
            (9, 0),     # no bulk
            (10, 5),
            (50, 10),
            (100, 15),
        ],
    )
    def test_total_bulk_discount(self, quantity, expected_percent):
        self.cart.add_item("bulk", 1.0, quantity)
        subtotal = quantity * 1.0
        discount_price = cart.apply_discount(subtotal, expected_percent)
        shipping = cart.shipping_fee(subtotal, member=False)
        total_expected = round(discount_price + shipping, 2)
        assert self.cart.total(member=False, coupon=None) == total_expected

    def test_total_coupon(self):
        self.cart.add_item("item", 50.0, 1)
        subtotal = 50.0
        discount_percent = cart.parse_coupon("SAVE20")
        discounted = cart.apply_discount(subtotal, discount_percent)
        shipping = cart.shipping_fee(discounted, member=False)
        total_expected = round(discounted + shipping, 2)
        assert self.cart.total(member=False, coupon="SAVE20") == total_expected

    def test_total_coupon_invalid(self):
        with pytest.raises(ValueError):
            self.cart.total(member=False, coupon="BADCODE")


# End of tests
